func novelReadDocuments(cmd *cobra.Command) ([]novelBacklogDoc, error) {
	exists, err := novelLocalStoreExists(cmd)
	if err != nil {
		return nil, err
	}
	if !exists {
		return []novelBacklogDoc{}, nil
	}
	db, err := novelOpenStore(cmd)
	if err != nil {
		return nil, err
	}
	defer db.Close()
	rows, err := db.DB().Query(`SELECT id, title, site_name, location, word_count, reading_time, saved_at, reading_progress, last_opened_at, created_at
		FROM documents
		WHERE COALESCE(parent_id, '') = ''`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	docs := make([]novelBacklogDoc, 0)
	for rows.Next() {
		var id string
		var title, site, loc, readingTime, saved, lastOpened, created sql.NullString
		var wordCount sql.NullInt64
		var progress sql.NullFloat64
		if err := rows.Scan(&id, &title, &site, &loc, &wordCount, &readingTime, &saved, &progress, &lastOpened, &created); err != nil {
			return nil, err
		}
		doc := novelBacklogDoc{
			ID:          id,
			Title:       cliutil.CleanText(title.String),
			SiteName:    cliutil.CleanText(site.String),
			Location:    loc.String,
			EstMinutes:  novelEstimateMinutes(readingTime.String, int(wordCount.Int64)),
			LengthKnown: wordCount.Int64 > 0 || novelReadingTimeKnown(readingTime.String),
			SavedAt:     novelParseTime(saved.String),
			ReadingProgress: func() float64 {
				if progress.Valid {
					return progress.Float64
				}
				return 0
			}(),
			LastOpenedAt: novelParseTime(lastOpened.String),
			CreatedAt:    novelParseTime(created.String),
		}
		if !doc.LengthKnown {
			doc.EstMinutes = 0
		}
		docs = append(docs, doc)
	}
	return docs, rows.Err()
}

func novelAgeBucket(now, saved time.Time) string {
	if saved.IsZero() {
		return "unknown"
	}
	age := now.Sub(saved)
	switch {
	case age < 7*24*time.Hour:
		return "<1w"
	case age < 4*7*24*time.Hour:
		return "1-4w"
	case age < 90*24*time.Hour:
		return "1-3mo"
	default:
		return ">3mo"
	}
}

func novelBacklogReport(docs []novelBacklogDoc, locations map[string]bool, budget time.Duration, sortMode string, now time.Time, includeUnknown ...bool) novelBacklogView {
	view := novelBacklogView{
		ByLocation: make([]novelBacklogBucket, 0),
		ByAge:      make([]novelBacklogBucket, 0),
		Worklist:   make([]novelBacklogWorkItem, 0),
	}
	if len(locations) == 0 {
		locations = novelCSVSet("new,later,shortlist", "")
	}
	for loc := range locations {
		view.Locations = append(view.Locations, loc)
	}
	sort.Strings(view.Locations)
	locBuckets := map[string]*novelBacklogBucket{}
	ageBuckets := map[string]*novelBacklogBucket{}
	unread := make([]novelBacklogDoc, 0)
	for _, doc := range docs {
		if len(locations) > 0 && !locations[strings.ToLower(doc.Location)] {
			continue
		}
		if doc.ReadingProgress < 1 {
			view.TotalDocuments++
			if doc.ReadingProgress == 0 {
				view.Totals.UnreadCount++
				view.Totals.EstimatedMinutes += doc.EstMinutes
				loc := doc.Location
				if loc == "" {
					loc = "unknown"
				}
				if locBuckets[loc] == nil {
					locBuckets[loc] = &novelBacklogBucket{Name: loc}
				}
				locBuckets[loc].Count++
				locBuckets[loc].EstimatedMinutes += doc.EstMinutes
				age := novelAgeBucket(now, doc.SavedAt)
				if ageBuckets[age] == nil {
					ageBuckets[age] = &novelBacklogBucket{Name: age}
				}
				ageBuckets[age].Count++
				ageBuckets[age].EstimatedMinutes += doc.EstMinutes
			}
		}
		if doc.ReadingProgress < 1 {
			if budget > 0 && !novelLengthKnown(doc) && !(len(includeUnknown) > 0 && includeUnknown[0]) {
				view.UnknownLengthExcluded++
			} else {
				unread = append(unread, doc)
			}
		}
		if doc.ReadingProgress > 0 && doc.ReadingProgress < 1 && (doc.LastOpenedAt.IsZero() || now.Sub(doc.LastOpenedAt) > 30*24*time.Hour) {
			view.Abandoned++
		}
	}
	for _, b := range locBuckets {
		view.ByLocation = append(view.ByLocation, *b)
	}
	sort.Slice(view.ByLocation, func(i, j int) bool { return view.ByLocation[i].Name < view.ByLocation[j].Name })
	for _, name := range []string{"<1w", "1-4w", "1-3mo", ">3mo", "unknown"} {
		if b := ageBuckets[name]; b != nil {
			view.ByAge = append(view.ByAge, *b)
		}
	}
	switch sortMode {
	case "saved":
		sort.SliceStable(unread, func(i, j int) bool { return unread[i].SavedAt.After(unread[j].SavedAt) })
	case "length":
		sort.SliceStable(unread, func(i, j int) bool { return unread[i].EstMinutes < unread[j].EstMinutes })
	default:
		sort.SliceStable(unread, func(i, j int) bool {
			pi := novelBacklogPriority(unread[i], budget, now)
			pj := novelBacklogPriority(unread[j], budget, now)
			if pi == pj {
				return unread[i].ID < unread[j].ID
			}
			return pi > pj
		})
	}
	remaining := int(budget.Minutes())
	for _, doc := range unread {
		if remaining <= 0 && budget > 0 {
			break
		}
		if budget > 0 && doc.EstMinutes > remaining {
			continue
		}
		score := novelBacklogPriority(doc, budget, now)
		item := novelBacklogWorkItem{ID: doc.ID, Title: doc.Title, SiteName: doc.SiteName, Location: doc.Location, EstMinutes: doc.EstMinutes, Minutes: novelMinutes(doc), LengthKnown: novelLengthKnown(doc), Score: score}
		if !doc.SavedAt.IsZero() {
			item.SavedAt = doc.SavedAt.Format(time.RFC3339)
		}
		view.Worklist = append(view.Worklist, item)
		if budget > 0 {
			remaining -= doc.EstMinutes
		}
	}
	return view
}

