func novelLengthKnown(doc novelBacklogDoc) bool { return doc.LengthKnown || doc.EstMinutes > 0 }
func novelMinutes(doc novelBacklogDoc) *int {
	if !novelLengthKnown(doc) {
		return nil
	}
	n := doc.EstMinutes
	return &n
}
func novelBacklogPriority(doc novelBacklogDoc, budget time.Duration, now time.Time) float64 {
	score := 0.0
	if !doc.SavedAt.IsZero() {
		score = 20 - now.Sub(doc.SavedAt).Hours()/24/7
		if score < 0 {
			score = 0
		}
	}
	switch strings.ToLower(doc.Location) {
	case "shortlist":
		score += 15
	case "later":
		score += 10
	case "new":
		score += 5
	}
	if doc.ReadingProgress > 0 && doc.ReadingProgress < 1 {
		score += 5
	}
	if budget > 0 && novelLengthKnown(doc) {
		diff := budget.Minutes() - float64(doc.EstMinutes)
		if diff >= 0 {
			score += 35 * (1 - diff/budget.Minutes())
		} else {
			score -= 20 + (-diff / budget.Minutes() * 20)
		}
	}
	return score
}

func novelReadingTimeKnown(raw string) bool {
	n, _ := strconv.Atoi(novelReadingDigitsRe.FindString(raw))
	return n > 0
}
